INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65982394', 65982394, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Suku Cadang Display Indoor DKI', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 153768000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 SET', 'Peningkatan kebutuhan masyarakat akan informasi terkait cuaca semakin signifikan seiring dengan berkembangnya aktivitas publik yang sangat bergantung pada kondisi cuaca. Informasi yang dibutuhkan mencakup berbagai aspek, seperti informasi cuaca umum, cuaca penerbangan, cuaca pelayaran, kondisi cuaca ekstrem, serta peringatan dini cuaca. Antara tahun 2010 hingga 2019, Badan Meteorologi, Klimatologi, dan Geofisika (BMKG) telah mengembangkan "Sistem Informasi Cuaca Publik" yang mencakup area publik, bandara, dan pelabuhan (indoor), dengan perangkat tampilan klien yang terpasang di wilayah DKI Jakarta. Aplikasi ini bertujuan untuk mendukung pelayanan informasi cuaca kepada masyarakat yang berada di area tersebut, serta memberikan akses mudah dan cepat untuk memperoleh informasi cuaca terkini. Untuk memastikan sistem aplikasi ini tetap berfungsi dengan optimal, pemeliharaan rutin pada perangkat keras dan perangkat lunak sangat diperlukan. Pemeliharaan ini bertujuan untuk mencegah terjadinya kerusakan atau gangguan yang dapat mempengaruhi kinerja sistem diseminasi informasi cuaca indoor. Dengan pemeliharaan yang baik, sistem ini dapat beroperasi secara maksimal dan dapat terus memberikan informasi yang akurat serta tepat waktu kepada masyarakat, instansi pemerintah, serta pihak-pihak terkait yang membutuhkan data cuaca untuk berbagai kepentingan. Melalui pemeliharaan berkala terhadap perangkat "Display Indoor", diharapkan aplikasi ini akan terus berjalan lancar dan dapat memberikan kemudahan bagi masyarakat dalam mengakses informasi cuaca. Dengan demikian, masyarakat dapat memperoleh informasi yang relevan dan penting mengenai kondisi cuaca di kota tujuan, yang dapat digunakan untuk berbagai keperluan seperti perencanaan perjalanan, kegiatan penerbangan, atau pelayaran.', 'Untuk mencapai tujuan yang diharapkan maka ditetapkan ruang lingkup pekerjaan “Pengadaan Suku Cadang Pemeliharaan Display Indoor” yang meliputi hal - hal sebagai berikut : 1. Pengadaan Mini PC Client display 2. Multi function Hub Adapter 3. PC All In One', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2490706);
