INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65982484', 65982484, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BANDAR UDARA MALIKUSSALEH', 'PEMELIHARAAN SARANA KANTOR', 'Barang', 'Pengadaan Langsung', 'Aceh, Aceh Utara (Kab.)', 420034000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 (satu) Paket', 'PEMELIHARAAN SARANA KANTOR - Genset - Wheel Tractor dan Rotary Mower - AC Terminal - X-Ray - WTMD - Mesin Potong Rumput - Tabung Pemadam Kebakaran - Instalasi Air - Instalasi Listrik - Perawatan Penunjang Keselamatan Penerbangan - Inventaris Kantor - Biaya Penggantian Inventaris Lama dan/atau Pembelian Inventaris untuk Pegawai Baru - AC Split - Komputer - Laptop - Printer', 'Spesifikasi Pekerjaan Pemeliharaan Sarana Kantor meliputi kegiatan pemeliharaan rutin, berkala, dan perbaikan terhadap seluruh peralatan operasional dan fasilitas pendukung guna menjamin kelancaran pelayanan dan keselamatan kerja. Ruang lingkup pekerjaan mencakup pemeriksaan, servis, dan pengujian fungsi genset; perawatan dan perbaikan wheel tractor, rotary mower, serta mesin potong rumput; pemeliharaan AC terminal dan AC split; pemeriksaan serta kalibrasi peralatan keamanan seperti X-Ray dan WTMD; pengecekan tekanan, masa berlaku, dan pengisian ulang tabung pemadam kebakaran; perbaikan instalasi air dan instalasi listrik; serta perawatan peralatan penunjang keselamatan penerbangan sesuai standar teknis. Selain itu, pekerjaan meliputi pengelolaan dan pemeliharaan inventaris kantor, termasuk komputer, laptop, dan printer, serta penggantian inventaris lama yang rusak atau tidak layak pakai dan/atau pengadaan inventaris bagi pegawai baru. Seluruh kegiatan dilaksanakan sesuai SOP, standar teknis pabrikan, ketentuan K3, serta peraturan yang berlaku untuk menjamin keandalan, keamanan, dan efisiensi operasional kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2490930);
