INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65984542', 65984542, 'analyze_legacy', 'Kementerian  Kehutanan', 'central', '693570 BALAI PENGELOLAAN DAERAH ALIRAN SUNGAI KAHAYAN', 'Petugas keamanan dan kebersihan persemaian permanen', 'Barang', 'Pengadaan Langsung', 'Kalimantan Tengah, Pulang Pisau (Kab.)', 110500000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Membersihkan, merawat area kantor, toilet, dan fasilitas umum untuk menciptakan lingkungannyaman dan higienis. dan Pengamanan Kantor', 'Lingkup Pekerjaan : Membersihkan, merawat area kantor, toilet, dan fasilitas umum untukmenciptakan lingkungan nyaman dan higienis. Kualifikasi Tenaga Kerja : Sertifikasi, pengalaman,pendidikan, dan fisik/kompetensi khusus yang wajib dipenuhi tenaga kerja. Standar OperasionalProsedur (SOP) : Metode pelaksanaan pekerjaan, jadwal kerja (shift), dan aturan seragam atauAPD. Manajemen Kinerja (SLA/KPI) : Indikator kinerja utama, mekanisme pengawasan olehpengawas, laporan bulanan, dan penalti jika hasil kerja tidak sesuai target. Tanggung JawabPenyedia Jasa : Pengurusan BPJS Kesehatan/Ketenagakerjaan, gaji, pelatihan, dan kewajibanmenyediakan tenaga kerja buffer (pengganti) jika ada yang absen. 1. Pengendalian Akses dan Tamu Pemeriksaan Tamu: Memeriksa identitas tamu, menukar KTPdengan kartu visitor, dan mencatat dalam buku tamu. Pengaturan Keluar Masuk: Mengawasigerbang/pagar kantor agar selalu tertutup dan aman, serta memeriksa kendaraan yang keluarmasuk. Penerimaan Paket/Surat: Menerima paket atau surat masuk di luar jam kerja atau saatresepsionis tidak di tempat. 2. Patroli dan Pengamanan Fisik Patroli Rutin: Berkeliling area kantor(dalam dan luar) untuk memastikan tidak ada aktivitas mencurigakan. Pengecekan Keamanan:Memeriksa pintu, jendela, pagar, dan memastikan lampu menyala/mati sesuai jadwal. MonitoringCCTV: Memantau layar pengawasan untuk mendeteksi potensi ancaman keamanan. 3. Ketertibandan Pelaporan Pembuatan Laporan: Membuat buku laporan harian, mutasi serah terima jaga, danlaporan kejadian (buku mutasi). Pelayanan Karyawan: Mengawasi absensi pegawai jika diperlukandan membantu keamanan kendaraan di parkiran. Tindakan Darurat: Menangani situasi darurat(kebakaran, pencurian) dan menghubungi pihak berwajib jika diperlukan. 4. Tugas TambahanPengawalan: Melakukan pengawalan tamu penting atau barang berharga atas izin atasan. SaranaPrasarana: Menghidupkan/mematikan mesin genset jika terjadi pemadaman listrik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2494680);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66024330', 66024330, 'analyze_legacy', 'Kota Metro', 'kabkota', 'Sekretariat DPRD', 'Belanja Sewa Alat Rumah Tangga Lainnya ( Home Use ) Sub Kegiatan Pelaksanaan Reses TA 2026', 'Barang', 'E-Purchasing', 'Lampung, Metro (Kota)', 11092500, 'January 2026', 'APBD', 1, 1, '1 TAHUN', 'Belanja Sewa Alat Rumah Tangga Lainnya ( Home Use ) Sub Kegiatan Pelaksanaan Reses TA 2026', 'Belanja Sewa Meja Kursi (Kursi Plastik)', 11092500, 'absurd', 'Pengadaan sewa meja kursi plastik untuk kegiatan reses legislatif dengan klasifikasi \'alat rumah tangga/home use\' menimbulkan kesan penggunaan anggaran yang tidak patut untuk kebutuhan seremonial/pendukung yang seharusnya dapat ditekan. Seluruh nilai pengadaan layak dicermati sebagai potensi pemborosan karena manfaat publik langsung dan urgensinya lemah dari informasi yang tersedia.', NULL, NULL, 4, 1, 1, 1, 1, 2494681);
