INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66025456', 66025456, 'analyze_legacy', 'Provinsi Sumatera Barat', 'provinsi', 'DINAS BINA MARGA, CIPTA KARYA DAN TATA RUANG', 'Pengadaan Jasa Lainnya Petugas Pengamat Jalan 1 UPTD Jalan dan Jembatan Wilayah I', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sumatera Barat, Pasaman (Kab.)', 32936123, 'February 2026', 'APBD', 1, 1, '1 Orang', 'Ruang lingkup Sub Kegiatan meliputi: 1. Pemantauan kondisi perkerasan jalan. 2. Pemantauankondisi bahu jalan dan sistem drainase. 3. Pemantauan perlengkapan jalan (rambu, patok, marka,guardrail). 4. Pemantauan kondisi jembatan (struktur atas, struktur bawah, lantai jembatan). 5.Identifikasi gangguan lalu lintas dan potensi bahaya. 6. Dokumentasi lapangan (foto dan titiklokasi). 7. Evaluasi kondisi dan penyusunan rekomendasi awal penanganan.', '1. Pendidikan minimal SMA/SMK atau sederajat, diutamakan berlatar belakang Teknik Sipil atau bidang lain yang relevan. 2. Sehat jasmani dan rohani, dibuktikan dengan surat keterangan sehatdari fasilitas pelayanan kesehatan. 3. Mampu melaksanakan pemantauan kondisi jalan dan/ataujembatan di lapangan secara rutin sesuai wilayah tugas yang ditetapkan. 4. Diutamakan memiliki pengalaman kerja di bidang pengamatan jalan, pemeliharaan jalan, atau pekerjaan lapangan sejenis paling singkat 1 (satu) tahun. 5. Mampu menyusun dan menyampaikan laporan hasil pengamatan lapangan secara sederhana, sistematis, dan tepat waktu. 6. Mampu bekerja secara mandiri maupun dalam koordinasi dengan Koordinator Pemantauan dan Evaluasi. 7. Bersedia mematuhi ketentuan keselamatan dan kesehatan kerja (K3) serta